return {
    ["name.appearance.bold"] = "Makes names and check-detail text heavier, by drawing each letter twice, a pixel apart. Icons, stars and outline thickness are unchanged.",
    ["name.appearance.font"] = "A font of Windows' own, by its file in C:\\Windows\\Fonts. Default is the font everything else is written in.",
    ["name.appearance.icon_outline"] = "Outline thickness for player, party-role, vendor, aggro/passive, sense and check icons, independent of Text Outline. Zero disables icon outlines without fading the artwork. Width follows name distance and render-resolution scaling. Aggro/passive icons remain shadow-free, but follow this width instead of the previous fixed one-pixel cap. Requires namehook 1.35 and WinXI 47; an older plugin leaves native names intact with an update warning. Mastery stars and letter badges retain their own rendering.",
    ["name.appearance.icon_outline_opacity"] = "Opacity of icon outlines only: 0% hides the outlines, 100% uses full configured outline-colour opacity. Icon fills, text outlines and name opacity are unchanged. Applies uniformly across outlined icon types and all player-icon sources; normal distance/entity fading still applies. Default 100%.",
    ["name.appearance.letter_spacing"] = "Extra space between the letters of every name, in pixels at the name's largest; it shrinks with the name. 0 is the font's own spacing. A [name], [level] or [distance] token's spacing= option sets its own, e.g. [name: spacing=2].",
    ["name.appearance.maximum_size"] = "Nearby name size shared by players, enemies and NPCs. Independent of health-bar dimensions.",
    ["name.appearance.minimum_size"] = "Smallest distant name size shared by every entity type.",
    ["name.appearance.outline"] = "Choose the text outline thickness. 0 disables text outlines without changing icon outlines. Icon Outline and Icon Outline Opacity control icons separately (requires namehook 1.35 and WinXI 47).",
    ["name.appearance.smooth_font"] = "Smooth Font builds a cached text atlas from glyphs rasterised at four times the normal resolution. Each output pixel averages the full source area, with transparent padding around the glyph. It can smooth curves and diagonals, especially under Lens. Off uses the original hinted glyphs for comparison.\n\nName size, spacing, baseline and outline thickness are kept. Bold works independently; icons and letter badges are unchanged. Uses more font-atlas memory and may soften very small text. Atlas generation happens on startup or font/size changes, not every frame. Direct glyph rendering is used while the atlas is preparing or unavailable. Off releases Name's generated atlas; ImGui may retain shared source-font atlas memory until it reclaims or rebuilds it. Disabled by default.",
    ["name.appearance.subtarget_size"] = "Size of the name under the subtarget cursor while choosing a target. 100% is normal size.",
    ["name.appearance.text_outline_opacity"] = "Opacity of the outline round text only: names, levels, distances, check details and cast text. 0% hides it, 100% is the outline colour's full opacity. Letters, icon outlines and name opacity are unchanged; distance fading still applies. Default 100%.",
    ["name.cast_bars.auto_width"] = "Widen health and cast bars to the visible entity name, counting visible letter badges as part of the name in either token order. Off by default. The saved Bar Width remains the minimum, so short names do not shrink the bars. Uses the rendered name/letter span and the spaces between, not cast captions, vendor/player icons or distance/check details. Both rows are centred under that span and stay aligned. Hidden name/letter tokens are not counted; formats with neither keep the saved width. Height is unchanged, and normal nameplate scaling still applies.",
    ["name.cast_bars.enabled"] = "Show observed spell casts under visible names. Uses the same width, height and starting position as HP bars; an enabled and eligible HP bar is drawn above it, including full HP while casting. The fill inherits the resolved entity-name colour (including explicit name-token colours and fading), with action name and timer below as the bar fills. Active casters remain detailed in crowd mode. Base timings are estimates (~), not live Fast Cast/modifier measurements. Finish/interrupt packets take precedence. If the estimate ends first, show Waiting with a full bar; unknown durations show elapsed time (+) with no fabricated fill. Casts already in progress when enabled cannot be recovered without a start packet.",
    ["name.cast_bars.name_scale"] = "Size of the action-name text relative to the nameplate font, independent of the timer. Default 75% preserves the original appearance; 25–200% is available. Does not change the bar dimensions or nameplate text. Large percentages upscale the existing font and may look softer. Status rows are moved down to clear the resized captions.",
    ["name.cast_bars.skill_text_only"] = "Show weaponskills and monster TP moves as their name and timer alone, with no bar, in the place the bar would start. On by default. Spells keep their bar. Needs Show Weaponskills.",
    ["name.cast_bars.texture"] = "What the cast bar is drawn in: Plain (the default) or one of WinXI's Bar Textures, as for health bars. It can differ from the health bars' texture. Weaponskills shown as text only have no bar.",
    ["name.cast_bars.timer_scale"] = "Size of the remaining/elapsed timer text relative to the nameplate font, independent of the action name. Default 75% preserves the original appearance; 25–200% is available. Used and Waiting use this size too. Does not change the bar dimensions; normal fading still applies.",
    ["name.cast_bars.weaponskills"] = "Also show readied weaponskills and monster TP moves, using estimated base preparation times where known. Completed/instant weaponskills briefly show their name and Used with a full bar; no fake charge-up is invented when there is no ready packet. Disabled by default. Spell and weaponskill bars stop on interrupts, death, despawn, zone change or a safety timeout. These are observations, not predictions of an enemy's next move.",
    ["name.cast_text.colour"] = "What the action name and timer are written in: White (the default), Name Colour (the same colour as the name and its cast bar) or Custom. Normal fading still applies.",
    ["name.cast_text.custom_colour"] = "The colour of the action name and timer when Text Colour is Custom.",
    ["name.cast_text.font"] = "The font the action name and timer are written in. Same as Names (the default) uses the names' font; Default is the font everything else is written in; or a .ttf from C:\\Windows\\Fonts. Bold follows the names' Bold. With Smooth Font on, a font of its own is drawn without the smoothing. A font that cannot be loaded falls back to the names' font.",
    ["name.cast_text.show_name"] = "Write the spell, weaponskill or TP move's name under the cast bar. On by default.",
    ["name.cast_text.show_timer"] = "Write the time left (~), the time so far (+), Waiting or Used under the action's name. On by default.",
    ["name.colours.section"] = "The states the game colours names by. An override applies together to name text, spawn letters and HP fill; a state not overridden keeps the game's colour. Icons and client opacity are unchanged.",
    ["name.colours.state"] = "Override this state for the name, letters and matching health-bar fill, including explicit name/letter token colours. Off: the game's colour for it. RGB only. Opacity, distance fading and disappearance fading remain controlled by the renderer; a target's name does not pulse.",
    ["name.diagnostics.custom_names"] = "Whether Name is drawing the names. When it stops for more than half a second the game draws its own, the reason is said in the chat log once, and a log is written.",
    ["name.diagnostics.enabled"] = "Record renderer problems and write a log when custom names stop.",
    ["name.diagnostics.in_view"] = "The names the game had to draw last frame: near enough, and on screen.",
    ["name.diagnostics.log"] = "Writes what Name and the namehook plugin are doing now, and what happened lately, to a small text file in config\\addons\\name\\logs. This detailed log can contain character names, paths, formats and raw errors. For sharing, prefer Write Report, which omits them.",
    ["name.diagnostics.report"] = "Write a shareable report to config\\addons\\name\\logs. Includes Name/WinXI/namehook capability-build versions, capability flags, display and draw counts, generated atlas dimensions, artwork source/fallback and recorded failure counts. Omits character/entity names, chat, paths, format strings, raw errors and history. Available without enabling diagnostics; recent failure history is collected only with diagnostics on. /name report also works when Enable Name is off. Nothing is uploaded.",
    ["name.enemies.check_abbreviate"] = "Use short difficulty labels beside detection/link details: TW, IEP, EP, DC, EM, T, VT and IT. Difficulty shown alone is in full words; Impossible to Gauge stays ???.",
    ["name.enemies.check_enabled"] = "Show difficulty, detection and linking information for five seconds after checking a monster.",
    ["name.enemies.check_size"] = "Size of check text and icons relative to the name. Applies to both display styles.",
    ["name.enemies.check_style"] = "Choose icons with text, or a text-only description, such as: TW, Sight Aggro, Link: Goblin (Sight). Detection can be Sight, Sound, Blood, Magic, JA, Scent and the true senses, several separated by a slash; Link names the monster family and how it detects.",
    ["name.format.enemy"] = "How enemy names are written, targeted and checked ones included. Tokens:\n[name] - the enemy's name.\n[level] - the level range the area's tables give, or the exact level once checked.\n[aggro] - the sign of whether it is aggressive, once known.\n[checked] - a magnifying glass once a check has told its level.\n[letters] - its spawn-slot letter, in stable entity-index order; [letter] is the same.\n[distance] - distance in yalms.\n[space] - a gap: [space: 8] for 8 px, 4 without. Only between two things written.\nAnything else is written as it is; a token with nothing known is left out.\n\nOptions go after a colon, e.g. [name: color=yellow, space=4]:\nAny token - color=yellow or #FF8000; space=0-64, pixels after it; when=target+checked+nm+relevant; within=1-100 yalms.\n[name], [level], [distance] - spacing=0-10, pixels between letters.\n[level] - exact, only a checked level; nocombat, none while it fights.\n[aggro], [checked] - size=25-300, % of the name's height.\n[letters] - type=single or double (AA, AB after Z).\n[distance] - decimals=0-2.\n\nExample format:\n[aggro] Lv [level]. [name] [letters] ([distance]y)\nExample result: [aggro icon] Lv 80-82. Goblin Butcher A (12.4y)",
    ["name.format.npc"] = "How NPC names are written. Tokens:\n[name] - the NPC's name.\n[vendor] - a coin for an NPC that sells: gil shops, guild merchants and outpost vendors.\n[icons] - the game's icons, when it gives any.\n[distance] - distance in yalms.\n[space] - a gap: [space: 8] for 8 px, 4 without. Only between two things written.\nAnything else is written as it is.\n\nOptions go after a colon, e.g. [name: color=yellow, space=4]:\nAny token - color=yellow or #FF8000; space=0-64, pixels after it; when=target+checked+nm+relevant; within=1-100 yalms.\n[name], [distance] - spacing=0-10, pixels between letters.\n[vendor], [icons] - size=25-300, % of the name's height.\n[icons] - gap=0-24, pixels between icons.\n[distance] - decimals=0-2.\n\nExample format:\n[vendor][name] ([distance]y)\nExample result: [coin] Babubu (4.2y)",
    ["name.format.player"] = "How player names are written. Tokens:\n[name] - the player's name.\n[party] - a party or alliance member's sign: Alliance Leader, Party Leader, another party's leader, Alliance Member or Party Member. None while you are alone.\n[icons] - the game's player icons.\n[distance] - distance in yalms.\n[space] - a gap: [space: 8] for 8 px, 4 without. Only between two things written.\nAnything else is written as it is.\n\nOptions go after a colon, e.g. [name: color=yellow, space=4]:\nAny token - color=yellow or #FF8000; space=0-64, pixels after it; when=target+checked+nm+relevant; within=1-100 yalms.\n[name], [distance] - spacing=0-10, pixels between letters.\n[icons], [party] - size=25-300, % of the name's height.\n[icons] - gap=0-24, pixels between icons.\n[party] - replace, its sign in place of the game's icons.\n[distance] - decimals=0-2.\n\nExample format:\n[party][icons][name] ([distance]y)\nExample result: [party sign][icons] Player Name (12.4y)",
    ["name.format.reset"] = "Restore this category's default format without changing other settings.",
    ["name.general.custom_names"] = "Enable Name's custom nameplates. Off: the game draws its own, as namehook sizes them (/namehook fontsize), unstretched; saved Visibility rules still say which are shown. Name's health bars and status icons are not drawn while it is off. All other Name settings are greyed out until enabled again; their saved values are kept.",
    ["name.general.preset"] = "A premade look: it sets the formats, health bars, status icons and check details. Font, sizes, colours, visibility and the chosen statuses are kept. Custom: the settings are none of these.",
    ["name.health_bars.combat_only"] = "Show bars only for the entity whose status is Engaged (1) and HP is above zero. Being targeted or claimed alone is not combat. Missing status data hides the bar. Applies to every type.",
    ["name.health_bars.enabled"] = "One shared health-bar setting for every entity, including pets/trusts and NPCs. Requires valid HP data. Full-health entities normally have no bar; while their cast bar is active, an enabled/eligible HP row stays visible above it so damage does not move the cast bar.",
    ["name.health_bars.entity_types"] = "Whether names of this kind have a health bar.",
    ["name.health_bars.height"] = "One height, including the border, for HP and cast bars. Both shrink with the name and use the same gap between rows. Action name and timer appear below the cast row, with statuses below those when configured underneath.",
    ["name.health_bars.preview"] = "Session-only preview of every bar that is enabled: each name that can have a health bar shows one, emptying and filling again, a little apart from the next, at full health and out of combat too (Combat Only is set aside; Health Bar Entity Types still apply); and with cast bars on, an animated sample cast under visible names, alternating spell and TP-move styles with Show Weaponskills. Real casts take precedence; no packets or actor records are made. Tune the shared size, Fit to Name, textures and cast text without waiting. Never saved; stops shortly after leaving this section or closing the window.",
    ["name.health_bars.texture"] = "What the bar is drawn in. Plain (the default) is the dark-bordered bar Name has always drawn. The others are WinXI's Bar Textures, the art party's HP bars use, tinted the name's colour. Shared Bar Size still sets its width and height; very small bars are drawn from a smaller copy of the art so they stay clean. The fill's end is softened with namehook 1.37; an older namehook draws it hard. If the art cannot be loaded, the bar is drawn Plain.",
    ["name.health_bars.width"] = "One width, including the border, for HP and cast bars, and the least they are with Fit to Name. Both use the same horizontal origin and shrink with the name. With both rows present, HP is above cast. Existing saved HP-bar widths are retained; the setting is editable when either kind of bar is enabled.",
    ["name.players.icon_source"] = "Artwork for the game's player-name icons and mastery stars. Game DATs reads the installed menu DAT and its glyph mapping, including Pivot replacements when redirect_fopens is enabled. Bundled uses Name's included atlas. Custom loads addons/name/assets/player-icons-custom.png with the bundled atlas layout and normal PNG alpha. Copy player-icons.png as a starting template; a higher-resolution version may use the same proportional layout. Missing or unsupported sources fall back to Bundled. Reload Name after changing artwork or Pivot packs. Party/alliance role icons, vendor and monster icons are independent.",
    ["name.players.icon_source_fallback"] = "The selected player-icon source could not be loaded; Name tries the bundled atlas instead. Your source selection is retained. Game DAT failures retry at most every ten seconds; reloading Name or switching sources also retries. Custom file loads retry through the shared image loader. Reason: {reason}",
    ["name.presets.default"] = "Player icons, enemy aggro and spawn letters, status icons and check details; no health bars.",
    ["name.presets.immersive"] = "Close to the game's own: names with player icons, and health bars only in combat; no levels, letters, status icons or check details.",
    ["name.presets.minimal"] = "Names alone: no icons, levels, bars, statuses or check details.",
    ["name.presets.robust"] = "Everything there is to know: enemy aggro, level, spawn letters and distance, health bars at all times, status icons and check details.",
    ["name.readability.crowd"] = "Optional and off by default. In a sustained crowd, simplify ordinary plates to their name, monster letters and aggro cue. Hide secondary text, player/vendor icons, stars, check details, HP bars and status rows. Never move plates or hide their core name. Your target, subtarget, yourself, party, alliance, own pet, whitelisted/charmed players, tracked NM/placeholders and observed active casters (with cast bars enabled) stay fully detailed. A deliberately name-less format remains name-less.",
    ["name.readability.crowd_hold"] = "The crowd condition must remain stable this long before details are hidden or restored. Combined with the three-name exit margin, this prevents flicker as people cross the screen edge. Targets and other protected plates remain fully detailed immediately.",
    ["name.readability.crowd_threshold"] = "Enter crowd mode when this many wanted, positive-scale name anchors are inside the output window. This is a crowd estimate, not overlap or occlusion detection. Exit only at three fewer names, and apply Hold Time both ways.",
    ["name.readability.distance"] = "Optional and off by default. Colour existing [distance] tokens at Warning and Danger thresholds. Explicit token colours take precedence; other tokens, text outlines, icons and layout are unchanged. These are measured distance thresholds, not guaranteed spell or ability ranges.",
    ["name.readability.distance_colors"] = "Tint only distance tokens without an explicit token colour. Nameplate fading still applies; opacity, other text and artwork are unaffected. The nearer band uses the token's usual inherited colour.",
    ["name.readability.distance_danger"] = "Use Danger Colour at or beyond this many yalms. At an equal Warning and Danger threshold, Danger takes precedence. No distance is invented when the client has no valid value.",
    ["name.readability.distance_hysteresis"] = "After a warning starts, distance must fall below its threshold minus this margin to clear it. Entry still happens at the configured threshold. This prevents colour flicker around a boundary; 0 disables the margin. The margin is limited to less than Warning Distance so the warning can always clear. State resets on identity, zone, configuration and enable changes.",
    ["name.readability.distance_warning"] = "Use Warning Colour at or beyond this many yalms, until Danger Distance is reached. The comparison uses the measured distance, not its rounded display. Danger Distance is kept at least as large as Warning Distance.",
    ["name.statuses.alignment"] = "Which side of the name the row is level with: its left, where its icons begin, its middle, or its right.",
    ["name.statuses.enabled"] = "Show the statuses selected below on visible nameplates. Your own and your party's statuses come from the game; everyone else's from effects seen in server messages, so effects applied out of sight or before you entered the area may be unknown.",
    ["name.statuses.entity_types"] = "Whether names of this kind have a row of statuses.",
    ["name.statuses.icons"] = "Which icons the statuses are drawn with. Winxi Theme follows Custom Icons in /wxi; Game Icons are the game's own; Custom Icons are the custom set's (the one chosen in /wxi, FFXIV to begin with), and the game's for a status the set has none for.",
    ["name.statuses.offset_x"] = "Moves the row right from where Position and Alignment put it, in screen pixels; below 0, left.",
    ["name.statuses.offset_y"] = "Moves the row down from where Position and Alignment put it, in screen pixels; below 0, up.",
    ["name.statuses.position"] = "Above the name, over the mastery stars where it has them, or below it, under the line a checked monster's details are written on while they are shown.",
    ["name.statuses.preview"] = "Puts the first few ticked statuses over every name that is shown, whatever it is really under, to see how the row looks. Not kept: it is off again when the addon is loaded.",
    ["name.statuses.search"] = "Part of a status's name, or its number. Only a ticked status is drawn over a name.",
    ["name.statuses.selected_only"] = "Lists only the statuses that are ticked.",
    ["name.statuses.size"] = "An icon's height, as a percentage of the height of the names. With custom icons, each is as wide as the set's icons are for that height; the game's are square.",
    ["name.tracking.monster"] = "Track a notorious monster in this area. Requires [aggro] in Mob Format and Show Aggro Icons. The choice is saved when you leave.",
    ["name.tracking.placeholders"] = "Replace placeholder names with \"Placeholder\". The rest of each nameplate is unchanged.",
